WITH cleaning_liquid_kind AS (
  SELECT product_kind_id FROM product_kinds WHERE product_kind_name = 'Cleaning Liquid'
),
cleaning_liquid_skus AS (
  SELECT pv.product_sku FROM product_variants pv JOIN cleaning_liquid_kind clk ON pv.product_kind_id = clk.product_kind_id
),
open_linz_stores AS (
  SELECT store_id FROM stores WHERE city = 'Linz' AND is_open = 1
),
eligible_inventory AS (
  SELECT si.product_sku FROM store_inventory si
  JOIN cleaning_liquid_skus cls ON si.product_sku = cls.product_sku
  JOIN open_linz_stores ols ON si.store_id = ols.store_id
  WHERE si.available_today_quantity > 0
)
SELECT COUNT(DISTINCT product_sku) AS count_val FROM eligible_inventory;
